using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class EndpointTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    public EndpointTests(WebApplicationFactory<Program> factory) => _factory = factory;

    private record PingDto(string message);
    private record SquareDto(int input, int result);

    [Fact]
    public async Task Ping_ReturnsPong()
    {
        var client = _factory.CreateClient();
        var resp = await client.GetAsync("/ping");
        resp.EnsureSuccessStatusCode();
        var dto = await resp.Content.ReadFromJsonAsync<PingDto>();
        Assert.Equal("pong", dto!.message);
    }

    [Fact]
    public async Task Square_ReturnsSquare()
    {
        var client = _factory.CreateClient();
        var resp = await client.GetAsync("/square/5");
        resp.EnsureSuccessStatusCode();
        var dto = await resp.Content.ReadFromJsonAsync<SquareDto>();
        Assert.Equal(25, dto!.result);
    }
}

